import re

# Get TRG data for P81-P128 from supp.pdf page10 (last 4 rows: 40-43) and page11 (all rows)
trg_rows_p10 = get_rows("supp.pdf", "page10")
trg_rows_p11 = get_rows("supp.pdf", "page11")
trg_rows = trg_rows_p10 + trg_rows_p11
trg_map = {}
for row_idx, row in enumerate(trg_rows, 1):
    if not row or len(row) < 8:
        continue
    patient_id = row[0]
    trg_val = row[7].lower()
    match = re.match(r"Patient-(\d+)", patient_id)
    if match:
        pid = int(match.group(1))
        if 81 <= pid <= 128:
            truth = 1 if trg_val in {"0", "1", "ccr"} else 0
            sheet = "page10" if row_idx <= len(trg_rows_p10) else "page11"
            row_in_sheet = row_idx if sheet == "page10" else row_idx - len(trg_rows_p10)
            trg_map[pid] = {
                "truth": truth,
                "ref": f"supp.pdf/{sheet}/R{row_in_sheet}C8"
            }

# Get organoid combined treatment ratio for P81-P128 from supp.pdf page13 (rows 41-44) and page14 (all rows)
ratio_rows_p13 = get_rows("supp.pdf", "page13")
ratio_rows_p14 = get_rows("supp.pdf", "page14")
ratio_rows = ratio_rows_p13 + ratio_rows_p14
ratio_map = {}
for row_idx, row in enumerate(ratio_rows, 1):
    if not row or len(row) < 5:
        continue
    patient_id = row[0]
    ratio_val = row[4]
    match = re.match(r"Patient(\d+)", patient_id)
    if match:
        pid = int(match.group(1))
        if 81 <= pid <= 128:
            try:
                ratio = float(ratio_val)
                score = 1 if ratio <= 0.3487 else 0
                sheet = "page13" if row_idx <= len(ratio_rows_p13) else "page14"
                row_in_sheet = row_idx if sheet == "page13" else row_idx - len(ratio_rows_p13)
                ratio_map[pid] = {
                    "score": score,
                    "ref": f"supp.pdf/{sheet}/R{row_in_sheet}C5",
                    "ratio": ratio
                }
            except ValueError:
                pass

# Add manual entries for missing P81 (if not found, reference article text for counts)
# Article reports: 20 sensitive organoids: 19 TP, 1 FP; 28 resistant: 26 TN, 2 FN; total 45 correct = 0.9375
# If some individual data is missing, we can use the aggregate counts with explicit reference
