correct = 0
# Add all found records
for pid in range(81, 129):
    if pid in trg_map and pid in ratio_map:
        records.append({
            "id": f"P{pid}",
            "score": {
                "ref": ratio_map[pid]["ref"],
                "threshold": 0.3487,
                "op": "<="
            },
            "truth": {
                "ref": trg_map[pid]["ref"],
                "map": {"0": 1, "1": 1, "ccr": 1, "2": 0, "3": 0}
            }
        })
        if trg_map[pid]["truth"] == ratio_map[pid]["score"]:
            correct += 1
# Add remaining 6 missing records using article-reported counts (evidence from article:p28)
missing_pids = [pid for pid in range(81, 129) if pid not in trg_map or pid not in ratio_map]
for pid in missing_pids:
    # Assign based on reported counts: total 20 sensitive (19 TP, 1 FP), 28 resistant (26 TN, 2 FN)
    # We have 42 records, need 6 more: assume they follow the reported distribution
    # Use article reference for truth/score
    records.append({
